declare function local:getQueryObject(){ let \$query : $=$ <query query_name $^ { \prime = }$ 'Item... 7 <param name $=$ 'Type' value $^ { \prime = }$ 'ProcessRes'/> </query> return Teamcenter:Query(\$teamcenter, \$query)   
};   
let \$processingResults : $\cdot =$ local:getQueryObject()   
for \$processingResult in \$processingResults   
return if(fn:count(\$processingResult[(@protocol = "Dash") and (@treatment $=$   
"Retin")]/F_GIN4_rel_Acquisition/GIN4 _Acquisition[@laterality_handless $=$ “Left   
handled” ]/B_ GIN4_rel_ExamenRes/GIN4_ExamRes[@examDate $< = ~ " 0 I$ January   
2013"]/B_GIN4_rel_ExamRes/GIN4_StudySub [(@ gin4_sex $=$ "M") and   
(@gin4_databirth $> = " { I 9 7 0 " ) } { \jmath } ) > 0 )$   
then (processingResult)   
else ()
